# -*- coding: utf-8 -*-
"""嵌入版 Python 启动钩子：绕开 primer3-py 的非 ASCII 路径段错误。

primer3-py 的 C++ 扩展在「包文件位于非 ASCII 路径」时构造 ThermoAnalysis
会 access violation 直接段错误（2026-09-11 实测 2.2.0/2.3.0/2.3.1 全中招；
junction、8.3 短路径均会被解析回真实路径，同样崩溃；与工作目录无关）。

对策：site-packages 不在纯 ASCII 路径时，把 primer3 包镜像到本机纯 ASCII 的
%ALLUSERSPROFILE%\\VirusPlatformPrimer3（约 2MB，首次启动自动复制，版本变化
时自动刷新），并把该目录插到 sys.path 最前。ASCII 环境下本钩子不做任何事。
镜像失败（如 ProgramData 只读）时静默跳过，仅引物设计相关功能可能不可用，
平台其余功能不受影响。
"""
import os
import shutil
import sys

_ASCII_MIRROR_DIRNAME = 'VirusPlatformPrimer3'


def _mirror_primer3():
    if os.name != 'nt':
        return
    sp = os.path.join(sys.prefix, 'Lib', 'site-packages')
    if sp.isascii() or not os.path.isdir(os.path.join(sp, 'primer3')):
        return
    base = os.environ.get('ALLUSERSPROFILE', r'C:\ProgramData')
    if not base.isascii():
        return
    dst_root = os.path.join(base, _ASCII_MIRROR_DIRNAME)
    dst = os.path.join(dst_root, 'primer3')

    cur_ver = None
    try:
        from importlib.metadata import PackageNotFoundError
        from importlib.metadata import version as _version
        cur_ver = _version('primer3-py')
    except PackageNotFoundError:
        return
    except Exception:
        pass

    marker = os.path.join(dst_root, 'VERSION.txt')
    need_refresh = True
    try:
        if os.path.exists(marker):
            with open(marker, encoding='utf-8') as fh:
                need_refresh = fh.read().strip() != (cur_ver or '')
        need_refresh = need_refresh or not os.path.isdir(dst)
    except OSError:
        need_refresh = True

    try:
        if need_refresh:
            os.makedirs(dst_root, exist_ok=True)
            if os.path.isdir(dst):
                shutil.rmtree(dst)
            shutil.copytree(os.path.join(sp, 'primer3'), dst)
            with open(marker, 'w', encoding='utf-8') as fh:
                fh.write(cur_ver or '')
        sys.path.insert(0, dst_root)
    except OSError:
        pass


_mirror_primer3()
